tokens.css:
--color-bg: #f6f1ea;
--color-surface: #fffdf9;
--color-text: #2b2420;
--color-text-muted: #6b5f58;
--color-border: #e4dbd0;
--color-primary: #9a4a6b;
--color-on-primary: #ffffff;
--color-accent: #c5523a;
--color-on-accent: #ffffff;
--font-display: "Fraunces", Georgia, serif;
--font-body: "Work Sans", system-ui, sans-serif;
--text-sm: 14px;
--text-base: 17px;
--text-lg: 21px;
--text-xl: 27px;
--text-2xl: 33px;
--text-3xl: 42px;
--radius-control: 6px;
--radius-card: 12px;
--space-section: 136px;
--shadow-card: 0 1px 2px color-mix(in oklab, var(--color-text) 8%, transparent), 0 10px 30px color-mix(in oklab, var(--color-text) 12%, transparent);
